from app.utils.sql_helpers import sql_guid
async def list_achievements(db,uid): return await db.execute_sql(f"DECLARE @u UNIQUEIDENTIFIER=(SELECT TOP 1 user_id FROM bc.app_user WHERE public_user_id={sql_guid(uid)});SELECT a.achievement_id achievementId,a.slug,a.title,a.description,a.achievement_group achievementGroup,a.target_value targetValue,a.icon_name iconName,CASE WHEN ua.user_id IS NULL THEN 0 ELSE a.target_value END currentValue,CAST(CASE WHEN ua.user_id IS NULL THEN 0 ELSE 1 END AS BIT) isUnlocked,ua.unlocked_at unlockedAt FROM bc.achievement_definition a LEFT JOIN bc.user_achievement ua ON ua.achievement_id=a.achievement_id AND ua.user_id=@u WHERE a.is_active=1 ORDER BY a.order_index;")
